/* Episode checklists belong to the saved full series, never to extra library entries. */
(function(root){
 function change(state,season,episodes,selected,done){const next=structuredClone(state||{seasons:{}});next.seasons||={};const old=next.seasons[season]||{watched:[]};const watched=new Set(old.watched);for(const id of selected)done?watched.add(id):watched.delete(id);next.seasons[season]={ids:[...new Set(episodes)],watched:[...watched]};return next;}
 function totals(state,seasons){let completed=0,total=0,known=true;for(const s of seasons){if(Number(s.facts?.['Season number'])===0)continue;const count=Number(s.facts?.Episodes);if(!Number.isInteger(count)||count<1)known=false;else total+=count;const row=state?.seasons?.[s.source.id];completed+=Math.min(count||Infinity,new Set((row?.watched||[]).filter(id=>!row?.ids||row.ids.includes(id))).size);}return {completed,total:known&&total?total:null};}
 function statusAfter(status,p){return p.total&&p.completed===p.total?'Completed':p.completed>0||status==='Completed'?'In progress':status;}
 if(typeof module==='object')module.exports={change,totals,statusAfter};if(typeof document==='undefined')return;
 function bind(section,media,records){const parent=(media.source_records||[media]).find(m=>m.source?.provider==='tmdb'&&m.kind==='tv'&&/^\d+$/.test(m.source.id));const seasons=records.filter(m=>m.source?.provider==='tmdb'&&m.format==='Season');if(!parent||!seasons.length)return;
  const entry=()=>items.find(x=>(x.metadata?.source_records||[x.metadata]).some(m=>m?.source?.provider==='tmdb'&&m.kind==='tv'&&m.source.id===parent.source.id));
  const panel=document.createElement('div');panel.className='series-progress-summary';panel.setAttribute('role','status');section.querySelector('.collection-groups').before(panel);
  const displays=[];
  function refresh(){const saved=entry(),p=totals(saved?.seriesProgress,seasons);panel.innerHTML=saved?`<strong>${saved.seriesProgress?`${p.completed}${p.total?' / '+p.total:''} episodes completed`:'Track episodes on this series'}</strong><p>${saved.seriesProgress?'Season checkmarks update overall progress. Specials are tracked separately.':saved.episodeProgress?.completed?'Starting a checklist replaces the manual count; your previous count is retained for reference.':'Mark a season, or expand it to check individual episodes. No separate library entries are created.'}</p>${saved.seriesProgress&&p.total?`<progress value="${p.completed}" max="${p.total}" aria-label="Series episode progress"></progress>`:''}${saved.seriesProgress&&saved.previousManualEpisodeProgress?.completed?`<small>Previous manual count: ${saved.previousManualEpisodeProgress.completed} episodes.</small>`:''}${saved.seriesProgress?'<button type="button" data-use-manual>Use manual progress</button>':''}`:'Add the full series to your library to save episode progress. Individual episodes do not need to be added.';
   panel.querySelector('[data-use-manual]')?.addEventListener('click',()=>{const x=entry();if(!x)return;const old=x.seriesProgress;delete x.seriesProgress;if(!persist()){x.seriesProgress=old;return;}refresh();});
   for(const draw of displays)draw();const dialog=section.closest('dialog');if(saved&&dialog?.id==='detail'){const done=dialog.querySelector('#episodes-done'),total=dialog.querySelector('#episodes-total'),unit=dialog.querySelector('#progress-unit');if(saved.seriesProgress){if(done)done.value=p.completed;if(total)total.value=p.total||'';if(unit)unit.value='Episodes';}for(const el of [done,total,unit,dialog.querySelector('#episode-form button[type=submit]')])if(el)el.disabled=!!saved.seriesProgress;const activity=dialog.querySelector('.activity-section');const noteCount=activity?.querySelector('progress + .muted');if(noteCount&&saved.seriesProgress)noteCount.textContent=`${p.completed} of ${p.total||'unknown'} completed`;const bar=dialog.querySelector('.activity-section progress');if(bar&&p.total){bar.max=p.total;bar.value=p.completed;}const note=dialog.querySelector('#episode-form .disclaimer');if(note)note.textContent=saved.seriesProgress?'Episode checklist controls progress automatically. Use the series checklist above, or choose Use manual progress.':'Use episode tracking for series or any episodic media. Progress won’t automatically mark the title completed.';}
  }
  function commit(season,episodes,selected,done){if(!selected.length)return;try{const latest=JSON.parse(localStorage.getItem('folio-library-v1')||'null');if(Array.isArray(latest))items=root.FolioLibraryPatch?root.FolioLibraryPatch.entries(latest):latest;}catch{}const x=entry();if(!x)return;const before=structuredClone(x);if(!x.seriesProgress&&x.episodeProgress?.completed&&!confirm('Use the episode checklist instead of your existing manual count? The previous count will be retained for reference.')){refresh();return;}
   if(!x.seriesProgress)x.previousManualEpisodeProgress=structuredClone(x.episodeProgress||{});x.seriesProgress=change(x.seriesProgress,season.source.id,episodes.map(m=>m.source.id),selected,done);x.episodeProgress=totals(x.seriesProgress,seasons);x.progressUnit='Episodes';const p=x.episodeProgress;x.status=statusAfter(x.status,p);
   if(!persist()){for(const k of Object.keys(x))delete x[k];Object.assign(x,before);refresh();return;}render();refresh();for(const select of section.closest('dialog').querySelectorAll('[data-status-id]'))if(select.dataset.statusId===x.id)select.value=x.status;toast(`${p.completed}${p.total?' / '+p.total:''} episodes completed`);
  }
  seasons.forEach(season=>{const index=records.indexOf(season),row=section.querySelector(`[data-part-view="${index}"]`)?.closest('.collection-row');if(!row)return;const controls=document.createElement('div');controls.className='season-check-controls';const mark=document.createElement('button');mark.type='button';controls.append(mark);row.append(controls);const details=document.createElement('details');details.className='season-episode-checklist';details.innerHTML='<summary>Episodes</summary><div class="season-check-list"></div>';row.after(details);let episodes=null,loading=false,error='';const list=details.querySelector('div');
   function draw(){const focused=list.contains(document.activeElement)?document.activeElement.dataset.episode:null;const saved=entry(),state=saved?.seriesProgress?.seasons?.[season.source.id],watched=new Set(state?.watched||[]),count=Number(season.facts?.Episodes)||0,all=count>0&&watched.size>=count;mark.textContent=loading?'Loading…':all?'✓ Season completed':'Mark season complete';mark.setAttribute('aria-pressed',String(all));mark.setAttribute('aria-label',(all?'Undo completion: ':'Complete: ')+season.title);mark.disabled=!saved||loading;mark.title=!saved?'Add the full series first':'';if(!episodes){list.textContent=error|| (loading?'Loading episodes…':'Expand to load episodes.');return;}list.innerHTML=episodes.map((m,i)=>`<label class="episode-check"><input type="checkbox" data-episode="${i}" ${watched.has(m.source.id)?'checked':''} ${!saved?'disabled':''}><span>${esc(m.title.replace(parent.title+' · ',''))}</span></label>`).join('')||'<p>No episodes supplied yet.</p>';list.querySelectorAll('input').forEach(el=>el.onchange=()=>commit(season,episodes,[episodes[Number(el.dataset.episode)].source.id],el.checked));if(focused!=null)list.querySelector(`[data-episode="${focused}"]`)?.focus({preventScroll:true});}
   async function load(){if(episodes)return true;if(loading)return false;loading=true;error='';draw();try{const data=await metadataGet(`collections/tmdb/tv/${season.source.id}`);episodes=data.groups.find(g=>g.title==='Episodes')?.results||[];return true;}catch(e){error='Episodes could not load. Close and reopen Episodes to retry.';return false;}finally{loading=false;draw();}}
   details.ontoggle=()=>{if(details.open)load();};mark.onclick=async()=>{if(await load()){const watched=new Set(entry()?.seriesProgress?.seasons?.[season.source.id]?.watched||[]);commit(season,episodes,episodes.map(m=>m.source.id),!episodes.length||!episodes.every(m=>watched.has(m.source.id)));}};displays.push(draw);draw();
  });
  function onSave(){if(!section.isConnected){document.removeEventListener('submit',onSave);return;}queueMicrotask(refresh);}
  document.addEventListener('submit',onSave);refresh();
 }
 root.FolioSeriesProgress={bind};
})(globalThis);
